"""Dependency-free, self-contained local reports and analyst workbenches."""
from pathlib import Path
import json,csv,html
from extract import ROOT
SEM='semiconductor-inventory-funding';RAIL='freight-rail-capital-review'
STYLE='''
:root{--navy:#102e36;--muted:#52676b;--teal:#087c78;--paper:#f5f3eb;--line:#cbd6d1;--gold:#b77825;--red:#a83c37}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--navy);font:16px/1.55 system-ui,sans-serif}header{background:var(--navy);color:white;padding:24px max(5vw,20px)}header a{color:#a8e5d8}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:var(--teal);text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,.scroll:focus-visible{outline:3px solid var(--gold);outline-offset:3px}main{max-width:1240px;margin:auto;padding:42px 5vw 70px}.eyebrow{text-transform:uppercase;letter-spacing:.13em;font-size:12px;font-weight:750;color:var(--teal)}h1{font:500 clamp(32px,5vw,56px)/1.08 Georgia,serif;max-width:870px;margin:16px 0 24px}h2{font:500 28px/1.2 Georgia,serif;margin:0 0 20px}h3{margin:8px 0}.lede{max-width:850px;font-size:20px;color:var(--muted)}.badge{display:inline-block;border:1px solid var(--red);color:var(--red);padding:5px 12px;font-size:13px;font-weight:700;border-radius:5px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:18px;margin:30px 0}.card,section{background:white;border:1px solid var(--line);border-radius:8px;padding:24px;min-width:0}.card .value{font-size:clamp(22px,3vw,32px);font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}.label{font-size:13px;color:var(--muted);margin:0 0 8px}section{margin:25px 0}.cols{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:25px}.cols section{margin:0}p{margin:8px 0 16px}.note{border-left:4px solid var(--gold);padding:15px 20px;background:#fff9e9}.controls{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));gap:16px;align-items:end}label{font-size:14px;font-weight:650;min-width:0}.select-bound{display:block;overflow:hidden;border:1px solid #849b9d;border-radius:4px;max-width:100%;background:white}.select-bound:focus-within{outline:3px solid var(--gold);outline-offset:3px}input,select,button{font:inherit;width:100%;min-width:0;border:1px solid #849b9d;border-radius:4px;padding:11px;background:white;color:var(--navy)}select{border:0}button{background:var(--teal);color:white;border:0;cursor:pointer}button.secondary{background:#e6efeb;color:var(--navy)}.scroll{overflow-x:auto;max-width:100%;border:1px solid var(--line);border-radius:5px}table{border-collapse:collapse;width:100%;min-width:600px;font-size:14px}th,td{padding:12px 15px;text-align:left;white-space:nowrap;border-bottom:1px solid var(--line)}th{background:#edf2ef}td.num{text-align:right;font-variant-numeric:tabular-nums}.quiet{color:var(--muted);font-size:14px}.error{color:var(--red);font-weight:650;min-height:25px}svg{width:100%;height:auto;display:block}.result{border-top:1px solid var(--line);margin-top:24px;padding-top:20px}footer{margin-top:40px;border-top:1px solid var(--line);padding-top:20px;font-size:13px;color:var(--muted)}@media(max-width:720px){.cols{grid-template-columns:1fr}main{padding:28px 18px 48px}section,.card{padding:18px}.lede{font-size:18px}.controls{grid-template-columns:minmax(0,1fr)}header{padding:20px}.cards{gap:12px}h1{font-size:36px}}
'''
def read(root,name):
 with (root/'outputs'/name).open() as f:return list(csv.DictReader(f))
def money(v):return ('$' if v>=0 else '−$')+f'{abs(v)/1e9:,.2f}B'
def bar_chart(labels,values,title,unit):
 mx=max(abs(x) for x in values)*1.15 or 1;H=70+len(labels)*60
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 {H}" role="img" aria-labelledby="chart-title"><title id="chart-title">{html.escape(title)}</title>']
 for i,(label,value) in enumerate(zip(labels,values)):
  y=35+i*60;w=abs(value)/mx*360
  out +=[f'<text x="5" y="{y+20}" font-family="sans-serif" font-size="16" fill="#102e36">{html.escape(label)}</text>',f'<rect x="190" y="{y}" width="{w:.3f}" height="30" rx="3" fill="{"#a83c37" if value<0 else "#087c78"}"/>',f'<text x="{200+w:.3f}" y="{y+21}" font-family="sans-serif" font-size="16" fill="#102e36">{value:,.2f}{unit}</text>']
 return ''.join(out)+'</svg>'
def page(title,body,isapp):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><style>{STYLE}</style></head><body><header><div class="eyebrow" style="color:#a8e5d8">PS / Independent finance research</div><nav aria-label="Project navigation"><a href="report.html">Research brief</a><a href="app.html">Analyst workbench</a><a href="executive_brief.md">Executive memo</a><a href="latest_decisions.csv">Decision data CSV</a></nav></header><main>{body}<footer>Source cutoff: 20 October 2026. Pinned SEC entity-wide XBRL and original filing evidence. Independent research prototype by Prathamesh Singh. Local/offline application; no hosted service. No investment or credit authorization.</footer></main></body></html>'''
def generate(project):
 root=ROOT/project;out=root/'outputs';m=json.loads((out/'metrics.json').read_text());latest=read(root,'latest_decisions.csv');semi=project==SEM
 title='Inventory funding, before the forecast' if semi else 'Reinvestment before cash returns'
 subtitle='Semiconductor manufacturing equipment' if semi else 'US listed freight railroads'
 decision=('Keep the last-balance baseline. The candidate model does not earn promotion, and two issuers have stale or incomplete current inputs.' if semi else 'Review distribution flexibility before discussing reinvestment cuts. Two issuers’ 2025 cash returns exceed operating cash after reported capital expenditure.')
 cards=([('Issuer-quarter records',str(m['records'])),('Model / baseline WAPE',f"{m['forecast_wape_pct']:.2f}% / {m['last_value_wape_pct']:.2f}%"),('Current usable issuers',f"{m['current_usable_issuers']} / {m['issuers']}")] if semi else [('Issuer-year records',str(m['records'])),('2025 residual after returns',money(m['latest_gap_usd'])),('Negative stress cases',f"{m['negative_gap_scenarios']} / {m['scenario_cases']}")])
 hero=f'<div class="eyebrow">Research note • 21 October 2026 • {subtitle}</div><h1>{title}</h1><p class="lede">{decision}</p><span class="badge">{"MODEL PROMOTION FAILED" if semi else "DILIGENCE ONLY — NO BUDGET APPROVAL"}</span><div class="cards">'+''.join(f'<div class="card"><div class="label">{a}</div><div class="value">{b}</div></div>' for a,b in cards)+'</div>'
 chart=bar_chart(['Candidate model','Last balance','Seasonal balance'],[m['forecast_wape_pct'],m['last_value_wape_pct'],m['seasonal_wape_pct']],'Held-out inventory forecast error: lower is better','%') if semi else bar_chart([r['ticker'] for r in latest],[float(r['distribution_gap'])/1e9 for r in latest],'2025 operating cash less capex, dividends and buybacks','$B')
 (out/'decision_evidence.svg').write_text(chart)
 findings=(f'''<p>The fixed 2022-selected ridge specification was tested on {m['forecast_test_cases']} later issuer-quarter outcomes across {m['test_issuer_clusters']} issuers. WAPE is {m['forecast_wape_pct']:.2f}%, versus {m['last_value_wape_pct']:.2f}% for the last-balance baseline. The approximate issuer-cluster interval for MAE improvement is ${m['mae_improvement_usd_interval95'][0]/1e6:,.2f}M to ${m['mae_improvement_usd_interval95'][1]/1e6:,.2f}M (negative means worse).</p><p>Prequential nominal 90% bands cover {m['coverage90_pct']:.2f}% of {m['interval_cases']} eligible test outcomes. Eleven early test forecasts have insufficient prior calibration after the information-timing guard. There are only five test issuer clusters; intervals have no guaranteed coverage under sector dependence.</p>''' if semi else f'''<p>For 2025, operating cash is {money(m['latest_cfo_usd'])}, reported cash capital expenditure is {money(m['latest_capex_usd'])}, and dividends plus repurchases are {money(m['latest_cash_returns_usd'])}. The resulting {money(m['latest_gap_usd'])} residual is an accounting funding gap, not evidence that specific buybacks were debt-funded.</p><p>{m['negative_gap_scenarios']} of {m['scenario_cases']} conditional CFO/capex scenarios have a negative residual after observed dividends and repurchases. The scenarios are a grid of assumptions, not probabilities. Net-versus-gross asset and tax/hurdle sensitivities expose denominator risk; these returns are not issuer ROIC.</p>''')
 limits=('The normalized panel excludes missing standardized facts rather than mapping Lam’s restructuring-excluded cost or Cohu’s tax-inclusive revenue into different concepts. LRCX is stale and COHU is historical-only. Current diagnostics cover four issuers. Inventory is a balance at cost, not committed procurement or cash outflow; payables, lead times, obsolescence, backlog and SKU constraints are missing.' if semi else 'The annual base ends December 2025, not today. Original current-period disclosures retain later revision differences. Union Pacific changes to finance-lease-inclusive assets in 2024; cross-basis return pairs are excluded. Maintenance versus growth capex, asset replacement cost, safety and merger obligations remain missing. A low accounting return does not justify cutting rail maintenance.')
 links='<a href="panel.csv">Normalized panel</a> · <a href="source_lineage.csv">Source lineage</a> · <a href="original_filing_reconciliation.csv">Original filing checks</a> · <a href="exclusions.csv">Exclusions</a> · <a href="later_revision_audit.csv">Revision differences</a>'
 report=hero+f'<div class="cols"><section><h2>{"The baseline wins" if semi else "Cash return capacity"}</h2><img src="decision_evidence.svg" alt="{html.escape("Forecast WAPE comparison" if semi else "Rail cash residual by issuer")}" style="width:100%;height:auto"><p class="quiet">{"2024–2026 observed outcomes. Actual filing dates gate training labels." if semi else "2025 GAAP cash flows, $B. Negative bars represent funding gaps."}</p></section><section><h2>Decision and evidence</h2>{findings}</section></div><section><h2>Boundaries that change the decision</h2><p>{limits}</p><p class="note">{"Do not use the candidate model to replace the baseline. Resolve the current-data exclusions and bring procurement evidence before setting a funding commitment." if semi else "Do not approve buybacks or capex cuts from this screen. Reconcile the current cash plan, committed investment and safety constraints with treasury first."}</p></section><section><h2>Audit trail</h2><p>{links}</p><p>Read the executive memo for the decision sequence; methods, source definitions, measured resume bullets and five implementation-based interview answers are in the project folder.</p><a href="app.html">Open analyst workbench →</a></section>'
 (out/'report.html').write_text(page(title,report,False))
 controls=('''<label>Forecast basis<span class="select-bound"><select id="basis" aria-label="Forecast basis"><option value="baseline">Last balance</option><option value="candidate">Rejected model</option></select></span></label><label>Annual carrying cost (%)<input id="assumptionA" aria-label="Annual carrying cost percent" type="number" value="10" min="0" max="40" step="1"></label><label>Inventory buffer (%)<input id="assumptionB" aria-label="Inventory buffer percent" type="number" value="0" min="0" max="50" step="1"></label>''' if semi else '''<label>CFO change (%)<input id="assumptionA" aria-label="CFO change percent" type="number" value="0" min="-60" max="20" step="1"></label><label>Capex versus base (%)<input id="assumptionB" aria-label="Capex versus base percent" type="number" value="100" min="80" max="150" step="1"></label>''')
 app=hero+f'''<section><h2>Explore the decision boundary</h2><p>{"Last balance is the default planning baseline. The rejected model can be inspected as a diagnostic only; its upper band is not a funding guarantee." if semi else "Use the disclosed 2025 cash-flow base. These changes are assumptions, not a forecast. The 80% capex floor is a UI boundary, not a safe maintenance budget."}</p><div class="controls"><label>Issuer<span class="select-bound"><select id="issuer" aria-label="Issuer">'''+''.join(f'<option value="{r["ticker"]}">{r["ticker"]}</option>' for r in latest)+f'''</select></span></label>{controls}<button id="calculate" type="button">Calculate</button><button id="reset" type="button" class="secondary">Reset</button></div><p id="error" role="alert" class="error"></p><div id="scenario" aria-live="polite" class="result"></div></section><section><h2>Issuer review queue</h2><label>Search issuers<input id="search" aria-label="Search issuers" placeholder="Ticker or status" type="search"></label><p id="count" aria-live="polite" class="quiet"></p><div class="scroll" tabindex="0" role="region" aria-label="Issuer decision table"><table id="decisions"><thead></thead><tbody></tbody></table></div><p class="quiet">Use the focused table region to scroll horizontally on narrow screens.</p></section><section><h2>How to use this review</h2><p>{limits}</p><p>{links}</p><a href="report.html">Read the research brief →</a></section>'''
 data={'kind':'semi' if semi else 'rail','latest':latest,'metrics':m}
 script=(ROOT/'workbench.js').read_text();app+=f'<script id="project-data" type="application/json">{json.dumps(data).replace("<", chr(92)+"u003c")}</script><script>{script}</script>'
 (out/'app.html').write_text(page(title,app,True))
if __name__=='__main__':
 for p in [SEM,RAIL]:generate(p)
